import type { EffectTemplateKind } from "./effectTemplates";

/**
 * Lazy URLs for the effect template thumbnails (Annie renders generated by
 * `pnpm -s effects:thumbnails`): Avatar FX at the folder's top level, Particle
 * and Scene FX in their own subfolders. Each image is a separate build asset
 * that is fetched only when its card is shown.
 */
const THUMBNAIL_LOADERS: Record<
  EffectTemplateKind,
  Record<string, () => Promise<string>>
> = {
  avatar: import.meta.glob<string>("../../assets/effect-templates/*.webp", {
    query: "?url",
    import: "default",
  }),
  particle: import.meta.glob<string>(
    "../../assets/effect-templates/particle/*.webp",
    { query: "?url", import: "default" },
  ),
  scene: import.meta.glob<string>(
    "../../assets/effect-templates/scene/*.webp",
    { query: "?url", import: "default" },
  ),
};

/** Each kind's loaders by template ID (the file's stem). */
const LOADERS_BY_KIND = Object.fromEntries(
  Object.entries(THUMBNAIL_LOADERS).map(([kind, loaders]) => [
    kind,
    new Map(
      Object.entries(loaders).map(([path, load]) => [
        path.replace(/^.*\/([^/]+)\.webp$/, "$1"),
        load,
      ]),
    ),
  ]),
) as Record<EffectTemplateKind, Map<string, () => Promise<string>>>;

/** The template IDs of `kind` that have a bundled thumbnail, sorted. */
export function effectTemplateThumbnailIds(kind: EffectTemplateKind): string[] {
  return [...LOADERS_BY_KIND[kind].keys()].sort();
}

/** Resolve one template's thumbnail URL, or null when none is bundled. */
export function loadEffectTemplateThumbnail(
  kind: EffectTemplateKind,
  id: string,
): Promise<string> | null {
  return LOADERS_BY_KIND[kind].get(id)?.() ?? null;
}
